// safe-dom.js — default-safe HTML construction for the admin dashboards.
//
// The dashboards build tables by string concatenation. Authored content (mob
// names, zone names, craft disciplines, spell and recipe names) and
// player-chosen character names both flow into those strings, so any markup
// stored in the world data or in a character name used to execute in the
// administrator's browser (review finding 17, stored XSS).
//
// The rule this file enforces: a value is escaped unless it is explicitly
// declared trusted with raw(). Trusted means "locally generated by this page
// from numbers", such as a progress bar or a score badge. Anything that came
// from the server as text is not trusted.
//
//     tr([ shop.name,                       // escaped
//          raw(fmtScore(shop.score)),       // trusted local fragment
//          { v: raw(bar), colspan: 5 } ])   // cell with attributes
//
// Loaded for every admin page from _header.html.
(function (global) {
    'use strict';

    var ENTITIES = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    };

    // esc renders any value as HTML-safe text. null and undefined become the
    // empty string rather than the words "null" / "undefined".
    function esc(value) {
        if (value === null || value === undefined) {
            return '';
        }
        return String(value).replace(/[&<>"']/g, function (c) {
            return ENTITIES[c];
        });
    }

    // Raw marks a string as already-safe HTML. Constructed only via raw(), so
    // every trust decision is greppable.
    function Raw(html) {
        this.html = String(html);
    }

    function raw(html) {
        return new Raw(html);
    }

    function isRaw(value) {
        return value instanceof Raw;
    }

    // render is the single escape decision: trusted fragments pass through,
    // everything else is escaped.
    function render(value) {
        return isRaw(value) ? value.html : esc(value);
    }

    // cellAttrs builds the attribute string for a
    // { v, colspan, cls, title, style } cell. Attribute values are escaped
    // too — these are not usually attacker-controlled, but nothing here relies
    // on that being true, and an unescaped quote would break out of the
    // attribute and reintroduce exactly the injection this file prevents.
    function cellAttrs(cell) {
        var attrs = '';
        if (cell.colspan) {
            attrs += ' colspan="' + esc(cell.colspan) + '"';
        }
        if (cell.cls) {
            attrs += ' class="' + esc(cell.cls) + '"';
        }
        if (cell.title) {
            attrs += ' title="' + esc(cell.title) + '"';
        }
        if (cell.style) {
            attrs += ' style="' + esc(cell.style) + '"';
        }
        return attrs;
    }

    // isCellSpec distinguishes a { v: ... } cell descriptor from a plain value.
    function isCellSpec(cell) {
        return cell !== null &&
            typeof cell === 'object' &&
            !isRaw(cell) &&
            Object.prototype.hasOwnProperty.call(cell, 'v');
    }

    function wrap(tag, cell) {
        if (isCellSpec(cell)) {
            return '<' + tag + cellAttrs(cell) + '>' + render(cell.v) + '</' + tag + '>';
        }
        return '<' + tag + '>' + render(cell) + '</' + tag + '>';
    }

    function td(cell) {
        return wrap('td', cell);
    }

    function th(cell) {
        return wrap('th', cell);
    }

    // tr builds a full table row from an array of cells.
    function tr(cells) {
        var out = '<tr>';
        for (var i = 0; i < cells.length; i++) {
            out += td(cells[i]);
        }
        return out + '</tr>';
    }

    // ths builds a run of header cells (no surrounding <tr>, matching how the
    // progression dashboard assigns straight into thead.innerHTML).
    function ths(cells) {
        var out = '';
        for (var i = 0; i < cells.length; i++) {
            out += th(cells[i]);
        }
        return out;
    }

    var api = {
        esc: esc,
        raw: raw,
        render: render,
        td: td,
        th: th,
        tr: tr,
        ths: ths
    };

    global.SafeDom = api;

    // Also exported for node so tools/jstest/safe-dom.test.js can exercise the
    // escaping without a browser. Harmless in the browser, where module is
    // undefined.
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = api;
    }
})(typeof window !== 'undefined' ? window : globalThis);
